namespace VFSTest
{
    /// A temporary folder with a name that is unique per test and per process, removed on destruction.
    class ScratchDir
    {
    public:
        ScratchDir()
        {
            static std::atomic<unsigned> counter{ 0 };
            static const unsigned salt = std::random_device{}();
            const testing::TestInfo* info = testing::UnitTest::GetInstance()->current_test_info();
            std::string name = std::format("vfs-{}-{}-{}-{}", info != nullptr ? info->test_suite_name() : "none",
                info != nullptr ? info->name() : "none", salt, counter++);
            for (char& c : name)
            {
                const bool digit = c >= '0' && c <= '9';
                const bool letter = (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z');
                if (!digit && !letter && c != '-')
                    c = '_';
            }
            mPath = TestingOpenMW::outputDir() / name;
            std::error_code ec;
            std::filesystem::remove_all(mPath, ec);
            std::filesystem::create_directories(mPath);
        }

        ScratchDir(const ScratchDir&) = delete;
        ScratchDir& operator=(const ScratchDir&) = delete;

        ~ScratchDir()
        {
            std::error_code ec;
            std::filesystem::remove_all(mPath, ec);
        }

        const std::filesystem::path& path() const { return mPath; }

        /// Creates a sub folder (and its parents) and returns its path.
        std::filesystem::path makeDir(const std::filesystem::path& relative) const
        {
            const std::filesystem::path result = mPath / relative;
            std::filesystem::create_directories(result);
            return result;
        }

    private:
        std::filesystem::path mPath;
    };

    inline void writeFile(const std::filesystem::path& path, std::string_view content)
    {
        std::filesystem::create_directories(path.parent_path());
        std::ofstream stream(path, std::ios::binary | std::ios::trunc);
        stream.write(content.data(), static_cast<std::streamsize>(content.size()));
        stream.flush();
        if (!stream)
            throw std::runtime_error("test helper could not write " + path.string());
    }

    inline std::string readAll(std::istream& stream)
    {
        return std::string(std::istreambuf_iterator<char>(stream), std::istreambuf_iterator<char>());
    }

    inline std::string readAll(const Files::IStreamPtr& stream)
    {
        return readAll(*stream);
    }

    /// Content of a file found through the manager, or "<missing>" when it is not found.
    inline std::string contentOf(const VFS::Manager& vfs, std::string_view name)
    {
        const Files::IStreamPtr stream = vfs.find(VFS::Path::Normalized(name));
        if (stream == nullptr)
            return "<missing>";
        return readAll(*stream);
    }

    /// All names under a prefix (all names when empty), in iteration order.
    inline std::vector<std::string> listNames(const VFS::Manager& vfs, std::string_view prefix)
    {
        std::vector<std::string> result;
        for (const VFS::Path::Normalized& name : vfs.getRecursiveDirectoryIterator(prefix))
            result.push_back(name.value());
        return result;
    }

    inline std::vector<std::string> listAllNames(const VFS::Manager& vfs)
    {
        std::vector<std::string> result;
        for (const VFS::Path::Normalized& name : vfs.getRecursiveDirectoryIterator())
            result.push_back(name.value());
        return result;
    }

    struct BsaEntry
    {
        std::string mName; // stored exactly as written (may use backslashes and upper case, like real archives)
        std::string mContent;
    };

    namespace detail
    {
        inline void appendLe32(std::string& out, std::uint32_t value)
        {
            // Tests run on little endian machines only (x64), like the existing BSA tests.
            char bytes[4];
            std::memcpy(bytes, &value, 4);
            out.append(bytes, 4);
        }
    }

    /// Bytes of an uncompressed (version 0x100, Morrowind) BSA with the given entries, in the given order.
    /// Layout (components/bsa/bsafile.cpp, BSAFile::readHeader): 12 byte header, then (size, offset) pairs, name
    /// offsets, names, 8 bytes of hash per file (ignored by the reader), then the data.
    inline std::string makeBsaBytes(const std::vector<BsaEntry>& entries)
    {
        std::string names;
        std::vector<std::uint32_t> nameOffsets;
        for (const BsaEntry& entry : entries)
        {
            nameOffsets.push_back(static_cast<std::uint32_t>(names.size()));
            names += entry.mName;
            names.push_back('\0');
        }

        const std::uint32_t count = static_cast<std::uint32_t>(entries.size());
        std::string out;
        detail::appendLe32(out, 0x100);
        detail::appendLe32(out, 12 * count + static_cast<std::uint32_t>(names.size()));
        detail::appendLe32(out, count);

        std::uint32_t dataOffset = 0;
        for (const BsaEntry& entry : entries)
        {
            detail::appendLe32(out, static_cast<std::uint32_t>(entry.mContent.size()));
            detail::appendLe32(out, dataOffset);
            dataOffset += static_cast<std::uint32_t>(entry.mContent.size());
        }
        for (const std::uint32_t offset : nameOffsets)
            detail::appendLe32(out, offset);
        out += names;
        out.append(8 * entries.size(), '\0'); // hash table
        for (const BsaEntry& entry : entries)
            out += entry.mContent;
        return out;
    }

    inline std::filesystem::path writeBsa(const std::filesystem::path& path, const std::vector<BsaEntry>& entries)
    {
        writeFile(path, makeBsaBytes(entries));
        return path;
    }

    /// The files an archive lists, by normalized name. The pointers stay valid as long as the archive does.
    inline VFS::FileMap listFiles(VFS::Archive& archive)
    {
        VFS::FileMap result;
        archive.listResources(result);
        return result;
    }

    /// Deterministic content of the given size where neighbouring offsets have different values.
    inline std::string patternContent(std::size_t size, unsigned seed = 1)
    {
        std::string out(size, '\0');
        for (std::size_t i = 0; i < size; ++i)
            out[i] = static_cast<char>((i * 7 + i / 251 + seed * 31 + 3) & 0xff);
        return out;
    }

    /// Registers folders (lowest priority first) and archive names (first = lowest priority among archives) the way
    /// the engine does.
    inline void registerAll(VFS::Manager& vfs, const std::vector<std::filesystem::path>& dataDirs,
        const std::vector<std::string>& archives, bool useLooseFiles = true)
    {
        const Files::Collections collections(dataDirs);
        VFS::registerBethesdaArchiveKinds();
        VFS::registerArchives(&vfs, collections, archives, useLooseFiles, nullptr);
    }
}

#endif
